<?php
require_once __DIR__ . '/../app/bootstrap.php'; require_once __DIR__ . '/../app/controllers/AdminFeatureController.php';
if (!Auth::check()) { header('Location: ' . APP_URL . '/admin-private-dnstl/login.php'); exit; } if (Auth::userRole() !== 'admin') { header('Location: ' . APP_URL . '/user-junkshop/dashboard.php'); exit; }
$controller = new AdminFeatureController(); $feedback = null; if ($_SERVER['REQUEST_METHOD'] === 'POST' && CSRF::verify()) $feedback = $controller->updateConcern((int) $_POST['concern_id'], (string) $_POST['status'], (string) ($_POST['admin_note'] ?? '')); $concerns = $controller->listConcerns(); $pageTitle = 'Concerns & Disputes'; $activePage = 'concerns'; ob_start();
?><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="fw-bold mb-1">Concerns & Disputes</h2><p class="text-muted mb-4">Review basic support tickets submitted by sellers and junkshop partners.</p><?php if ($feedback): ?><div class="alert alert-<?php echo $feedback['success'] ? 'success' : 'danger'; ?>"><?php echo Validator::escape($feedback['message']); ?></div><?php endif; ?><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Reporter</th><th>Concern</th><th>Status</th><th>Admin resolution</th></tr></thead><tbody><?php foreach ($concerns as $concern): ?><tr><td><?php echo Validator::escape($concern['reporter_name']); ?><br><span class="small text-muted"><?php echo Validator::escape($concern['reporter_email']); ?></span></td><td><strong><?php echo Validator::escape($concern['subject']); ?></strong><br><span class="small"><?php echo nl2br(Validator::escape($concern['description'])); ?></span></td><td><span class="badge text-bg-secondary"><?php echo Validator::escape($concern['status']); ?></span><br><span class="small text-muted"><?php echo Validator::escape($concern['created_at']); ?></span></td><td><form method="post"><input type="hidden" name="_csrf_token" value="<?php echo CSRF::token(); ?>"><input type="hidden" name="concern_id" value="<?php echo (int) $concern['id']; ?>"><select class="form-select form-select-sm mb-2" name="status"><option <?php echo $concern['status'] === 'Open' ? 'selected' : ''; ?>>Open</option><option <?php echo $concern['status'] === 'In Review' ? 'selected' : ''; ?>>In Review</option><option <?php echo $concern['status'] === 'Resolved' ? 'selected' : ''; ?>>Resolved</option><option <?php echo $concern['status'] === 'Closed' ? 'selected' : ''; ?>>Closed</option></select><textarea class="form-control form-control-sm mb-2" name="admin_note" rows="2" placeholder="Resolution note"><?php echo Validator::escape($concern['admin_note'] ?? ''); ?></textarea><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php $content = ob_get_clean(); require_once __DIR__ . '/../app/views/admin_dashboard_shell.php';